int main() {
    // Test parameters
    double S = 100.0;
    double K = 100.0;
    double r = 0.05;
    double sigma = 0.2;
    double T = 1.0;
    int n = 12;
    unsigned long long nPaths = 1000000;
    unsigned int seed = 12345;

    std::cout << "Testing Asian option pricer with:" << std::endl;
    std::cout << "S = " << S << ", K = " << K << ", r = " << r 
              << ", sigma = " << sigma << ", T = " << T << ", n = " << n 
              << ", paths = " << nPaths << ", seed = " << seed << std::endl;

    McResult result = gpu_asian_call(S, K, r, sigma, T, n, nPaths, seed, 0);

    std::cout << "Price: " << result.price << std::endl;
