    for (unsigned long long path = tid; path < nPaths; path += total_threads) {
        // Initialize random state for this path
        unsigned int state = seed + path;
        for (int i = 0; i < 16; i++) lcg(state);

        float x = 0, sum = 0;
        for (int k = 0; k < n; k++) {
            x += drift + vol * gauss(state);
            sum += S * expf(x);
        }
        float pay = sum / n - K;
        if (pay < 0) pay = 0;

        // Use atomic operations to safely accumulate results
        atomicAdd(&tally[0].sum, pay);
        atomicAdd(&tally[0].sq, pay * pay);
        atomicAdd(&tally[0].count, 1);
    }
}

McResult gpu_asian_call(double S, double K, double r, double sigma, double T, int n,
                        unsigned long long nPaths, unsigned int seed, int device) {
    cudaSetDevice(device);

    // Use a reasonable number of blocks and threads
    const int threads = 256;
    const int max_blocks = 1024;  // Limit to prevent excessive resource usage
    int blocks = (int)((nPaths + threads - 1) / threads);
    if (blocks > max_blocks) blocks = max_blocks;

    // Allocate memory for tally with a small buffer (256KB max)
    Tally* d;
    size_t max_tally_size = 256 * 1024 * 1024 / sizeof(Tally);  // 256MB limit
    size_t tally_size = (max_tally_size < 1024) ? max_tally_size : 1024;  // Use 1024 elements max
    cudaMalloc(&d, sizeof(Tally) * tally_size);

    // Initialize tally to zero
    Tally zero = {0, 0, 0};
    cudaMemset(d, 0, sizeof(Tally));

    // Calculate proper time step for Asian option
    float dt = T / n;
    float drift = (r - 0.5 * sigma * sigma) * dt;
    float vol = sigma * sqrtf(dt);

    // Launch kernel
    asian_kernel<<<blocks, threads>>>(S, K, drift, vol, n, nPaths, seed, d);

    // Check for kernel launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        // Handle error appropriately
        return {0.0, 0.0, 0};
    }

    // Wait for kernel to complete
    cudaDeviceSynchronize();

    // Copy result back
    Tally h;
    cudaMemcpy(&h, d, sizeof(Tally), cudaMemcpyDeviceToHost);

    // Calculate final results
    double m = double(h.sum) / h.count;
    double v = double(h.sq) / h.count - m * m;
    double df = exp(-r * T);

    // Clean up
    cudaFree(d);

    return {df * m, df * sqrt(v / nPaths), h.count};
}

